interface Handler {
  setNext(handler: Handler): Handler;
  handle(request: any): any | null;
}
class ConcreteHandler implements Handler {
  private next?: Handler;
  setNext(handler: Handler) { this.next = handler; return handler; }
  handle(request: any) { if (request.type === 'A') return 'handled A'; return this.next ? this.next.handle(request) : null; }
}

interface Handler { setNext(h: Handler): Handler; handle(req: any): any | null; }
class AuthHandler implements Handler {
  private next?: Handler;
  setNext(h: Handler) { this.next = h; return h; }
  handle(req: any) { if (!req.auth) return null; return this.next ? this.next.handle(req) : null; }
}
// chain assembled at runtime
const chain = new AuthHandler();
chain.setNext(new LoggingHandler()).setNext(new DataHandler());

// Version A: multiple small handler classes linked at runtime
interface Handler { setNext(h: Handler): Handler; handle(req: any): any | null; }
class AuthHandler implements Handler { /* checks auth and forwards */ }
class LoggingHandler implements Handler { /* logs and forwards */ }
// Version B: single processor with long conditional chain
class Processor {
  process(req: any) {
    if (req.type === 'auth') { /* auth logic */ }
    else if (req.type === 'log') { /* logging logic */ }
    else { /* other logic */ }
  }
}
